def create_invoice_handler(service, user, body):
    """POST /invoices: returns (status, body)."""
    try:
        items = []
        for item_data in body.get("items", []):
            items.append(LineItem(
                sku=item_data["sku"],
                qty=item_data["qty"],
                unit_paise=item_data["unit_paise"]
            ))

        inv = Invoice(
            id=body["id"],
            customer=user,
            items=items
        )
        service.create(inv)
        return 201, {
            "id": inv.id,
